#!/usr/bin/env python3
from pathlib import Path
import json,hashlib,subprocess,argparse,time,re
T=Path(__file__).resolve().parents[1];p=argparse.ArgumentParser();p.add_argument('--run',required=True);p.add_argument('--jobs',type=int,default=32);a=p.parse_args();assert a.jobs==32 and re.fullmatch(r'[A-Za-z0-9_-]+',a.run);O=T/'.build'/a.run/'ordinary';O.mkdir(parents=True,exist_ok=False);src=T/'shim/ordinary.c';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();h=sha(src);(O/'ordinary.c').write_bytes(src.read_bytes());cmd=['/usr/bin/prlimit','--as=17179869184','--cpu=7200','--','/tmp/qcp214-src/linux-binary/symexec','--arch=64','--endian=little','--no-float-finite-vc','--no-exec-info','--no-record-strategies','--input-file='+str(O/'ordinary.c'),'--coq-output-dir='+str(O),'--coq-logic-path=QC4Ordinary'];t=time.monotonic()
